  {value: Lang.En, content: 'English'},
  {value: Lang.Ru, content: 'Русский'},
];

export function LangSwitcher() {
  const {lang, setLang} = useI18n();

  return (
    <Select
      value={[lang]}
      onUpdate={(value) => setLang(value[0] as Lang)}
      options={options}
    />
  );
}
